kamyu-c-subtree-inversion-sum-ii-1k1m2b3:
// Time:  O(n * k)
// Space: O(n + h * k)

// iterative dfs, tree dp
class Solution {
public:
    int subtreeInversionSum(vector<vector<int>>& edges, vector<int>& nums, int k) {
        vector<vector<int>> adj(size(nums));
        const auto& iter_dfs = [&]() {
            using RET = vector<vector<int64_t>>;
            RET result{};
            vector<tuple<int, int, int, int, shared_ptr<RET>, RET *>> stk = {{1, 0, -1, -1, nullptr, &result}};
            while (!empty(stk)) {
                const auto [step, u, p, i, new_ret, ret] = stk.back(); stk.pop_back();
                if (step == 1) {
                    ret->assign(2, vector<int64_t>(k, nums[u]));
                    stk.emplace_back(4, -1, -1, -1, nullptr, ret);
                    stk.emplace_back(2, u, p, 0, nullptr, ret);
                } else if (step == 2) {
                    if (i == size(adj[u])) {
                        continue;
                    }
                    const auto& v = adj[u][i];
                    stk.emplace_back(2, u, p, i + 1, nullptr, ret);
                    if (v == p) {
                        continue;
                    }
                    const auto& new_ret = make_shared<RET>();
                    stk.emplace_back(3, -1, -1, -1, new_ret, ret);
                    stk.emplace_back(1, v, u, -1, nullptr, new_ret.get());
                } else if (step == 3) {
                    auto& new_dp1 = (*new_ret)[0], &new_dp2 = (*new_ret)[1];
                    auto& dp1 = (*ret)[0], &dp2 = (*ret)[1];
                    for (int i = 0; i < k / 2; ++i) {
                        dp1[i] = max(dp1[i] + new_dp1[(k - 2) - i], dp1[(k - 2) - i] + new_dp1[i]);
                        dp2[i] = min(dp2[i] + new_dp2[(k - 2) - i], dp2[(k - 2) - i] + new_dp2[i]);
                    }
                    for (int i = k / 2; i < k; ++i) {
                        dp1[i] += new_dp1[i];
                        dp2[i] += new_dp2[i];
                    }
                    for (int i = k - 2; i >= 0; --i) {
                        dp1[i] = max(dp1[i], dp1[i + 1]);
                        dp2[i] = min(dp2[i], dp2[i + 1]);
                    }
                } else if (step == 4) {
                    auto& dp1 = (*ret)[0], &dp2 = (*ret)[1];
                    const auto mx = max(dp1[0], -dp2[k - 1]);
                    const auto mn = min(dp2[0], -dp1[k - 1]);
                    dp1.insert(begin(dp1), mx); dp1.pop_back();
                    dp2.insert(begin(dp2), mn); dp2.pop_back();
                }
            }
            return result[0][0];
        };

        for (auto& e : edges) {
            adj[e[0]].emplace_back(e[1]);
            adj[e[1]].emplace_back(e[0]);
        }
        return iter_dfs();
    }
};

// Time:  O(n * k)
// Space: O(n + h * k)
// dfs, tree dp
class Solution2 {
public:
    int subtreeInversionSum(vector<vector<int>>& edges, vector<int>& nums, int k) {
        vector<vector<int>> adj(size(nums));
        const auto dfs = [&](this auto&& dfs, int u, int p) -> pair<vector<int64_t>, vector<int64_t>> {
            vector<int64_t> dp1(k, nums[u]), dp2(k, nums[u]);
            for (const auto& v : adj[u]) {
                if (v == p) {
                    continue;
                }
                const auto& [new_dp1, new_dp2] = dfs(v, u);
                for (int i = 0; i < k / 2; ++i) {
                    dp1[i] = max(dp1[i] + new_dp1[(k - 2) - i], dp1[(k - 2) - i] + new_dp1[i]);
                    dp2[i] = min(dp2[i] + new_dp2[(k - 2) - i], dp2[(k - 2) - i] + new_dp2[i]);
                }
                for (int i = k / 2; i < k; ++i) {
                    dp1[i] += new_dp1[i];
                    dp2[i] += new_dp2[i];
                }
                for (int i = k - 2; i >= 0; --i) {
                    dp1[i] = max(dp1[i], dp1[i + 1]);
                    dp2[i] = min(dp2[i], dp2[i + 1]);
                }
            }
            const auto mx = max(dp1[0], -dp2[k - 1]);
            const auto mn = min(dp2[0], -dp1[k - 1]);
            dp1.insert(begin(dp1), mx); dp1.pop_back();
            dp2.insert(begin(dp2), mn); dp2.pop_back();
            return pair(dp1, dp2);
        };

        for (auto& e : edges) {
            adj[e[0]].emplace_back(e[1]);
            adj[e[1]].emplace_back(e[0]);
        }
        const auto& [dp1, _] = dfs(0, -1);
        return dp1[0];
    }
};

kamyu-c-subtree-inversion-sum-0bgx4qg:
// Time:  O(n)
// Space: O(n)

// iterative dfs, tree dp
class Solution {
public:
    long subtreeInversionSum(const vector<vector<int>>& edges, const vector<int>& nums, int k) {
        vector<vector<int>> adj(size(nums));
        vector<pair<int64_t, int64_t>> dp;
        const auto& iter_dfs = [&]() {
            vector<pair<int64_t, int64_t>> dp;
            using RET = vector<int64_t>;
            RET ret(3);
            vector<tuple<int, int, int, int, shared_ptr<RET>, RET *>> stk = {{1, 0, -1, -1, nullptr, &ret}};
            while (!empty(stk)) {
                const auto [step, u, p, i, new_ret, ret] = stk.back(); stk.pop_back();
                if (step == 1) {
                    dp.emplace_back(0, 0);
                    (*ret) = {nums[u], 0, 0};
                    stk.emplace_back(4, u, p, -1, nullptr, ret);
                    stk.emplace_back(2, u, p, 0, nullptr, ret);
                } else if (step == 2) {
                    if (i == size(adj[u])) {
                        continue;
                    }
                    const auto& v = adj[u][i];
                    stk.emplace_back(2, u, p, i + 1, nullptr, ret);
                    if (v == p) {
                        continue;
                    }
                    const auto& new_ret = make_shared<RET>(3);
                    stk.emplace_back(3, u, p, i, new_ret, ret);
                    stk.emplace_back(1, v, u, -1, nullptr, new_ret.get());
                } else if (step == 3) {
                    (*ret)[0] += (*new_ret)[0];
                    (*ret)[1] += (*new_ret)[1];
                    (*ret)[2] += (*new_ret)[2];
                } else if (step == 4) {
                    (*ret)[1] = max((*ret)[1], dp.back().second - 2 * (*ret)[0]);
                    (*ret)[2] = max((*ret)[2], dp.back().first + 2 * (*ret)[0]);
                    dp.pop_back();
                    if (size(dp) >= k) {
                        dp[size(dp) - k].first += (*ret)[1];
                        dp[size(dp) - k].second += (*ret)[2];
                    }
                }
            }
            return ret[0] + ret[1];
        };

        for (const auto& e: edges) {
            adj[e[0]].emplace_back(e[1]);
            adj[e[1]].emplace_back(e[0]);
        }
        return iter_dfs();
    }
};

// Time:  O(n)
// Space: O(n)
// dfs, tree dp
class Solution2 {
public:
    long subtreeInversionSum(const vector<vector<int>>& edges, const vector<int>& nums, int k) {
        vector<vector<int>> adj(size(nums));
        vector<pair<int64_t, int64_t>> dp;
        const function<tuple<int64_t, int64_t, int64_t> (int, int)> dfs = [&](int u, int p) {
            dp.emplace_back(0, 0);
            int64_t total = nums[u];
            int64_t pos = 0;
            int64_t neg = 0;
            for (const auto& v: adj[u]) {
                if (v == p) {
                    continue;
                }
                const auto& [new_total, new_pos, new_neg] = dfs(v, u);
                total += new_total;
                pos += new_pos;
                neg += new_neg;
            }
            pos = max(pos, dp.back().second - 2 * total);
            neg = max(neg, dp.back().first + 2 * total);
            dp.pop_back();
            if (size(dp) >= k) {
                dp[size(dp) - k].first += pos;
                dp[size(dp) - k].second += neg;
            }
            return tuple(total, pos, neg);
        };

        for (const auto& e: edges) {
            adj[e[0]].emplace_back(e[1]);
            adj[e[1]].emplace_back(e[0]);
        }
        const auto& [total, pos, neg] = dfs(0, -1);
        return total + pos;
    }
};

kamyu-c-subtree-of-another-tree-0miclb9:
// Time:  O(m * n), m is the number of nodes of s, n is the number of nodes of t
// Space: O(h), h is the height of s

/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode(int x) : val(x), left(NULL), right(NULL) {}
 * };
 */
class Solution {
public:
    bool isSubtree(TreeNode* s, TreeNode* t) {
        return preOrderTraverse(s, t);
    }

private:
    bool preOrderTraverse(TreeNode *s, TreeNode *t) {
        return s && (isSame(s, t) ||
                     preOrderTraverse(s->left, t) ||
                     preOrderTraverse(s->right, t));
    }

    bool isSame(TreeNode *x,TreeNode *y) {
        if (!x && !y) {
            return true;
        }
        if (!x || !y) {
            return false;
        }
        return x->val == y->val &&
               isSame(x->left, y->left) &&
               isSame(x->right, y->right);
    }
};

kamyu-c-subtree-removal-game-with-fibona:
// Time:  O(1)
// Space: O(1)

class Solution {
public:
    bool findGameWinner(int n) {
        // a pattern appears every 6 grundy numbers in binary forms:
        // 0000,       (0000)01,       (0000)11,                 ((0000)^(0000+1))10,       (0000)11,       (0000)11
        // 0000,     (0000+1)01,     (0000+1)11,           ((0000+1)^((0000+1)+1))10,     (0000+1)11,     (0000+1)11
        // 0000, ((0000+1)+1)01, ((0000+1)+1)11,   (((0000+1)+1)^(((0000+1)+1)+1))10, ((0000+1)+1)11, ((0000+1)+1)11
        // ...
        // 0000,       (XXXX)01,       (XXXX)11,                 ((XXXX)^(XXXX+1))10,       (XXXX)11,       (XXXX)11
        // 0000,     (XXXX+1)01,     (XXXX+1)11,           ((XXXX+1)^((XXXX+1)+1))10,     (XXXX+1)11,     (XXXX+1)11
        // => grundy[6k+1] = 0
        //    grundy[6k+2] = 4k+1
        //    grundy[6k+3] = 4k+3
        //    grundy[6k+4] = 4(k^(k+1))+2
        //    grundy[6k+5] = 4k+3
        //    grundy[6k+6] = 4k+3
        return n % 6 != 1;
    }
};

// Time:  O(n)
// Space: O(1)
class Solution2 {
public:
    bool findGameWinner(int n) {
        vector<int> grundy = {0, 1};  // 0-indexed
        for (int i = 2; i < n; ++i) {
            grundy[i % 2] = (grundy[(i - 1) % 2] + 1) ^ (grundy[(i - 2) % 2] + 1);  // colon principle, replace the branches by a non-branching stalk of length equal to their nim sum
        }
        return grundy[(n - 1) % 2];
    }
};

kamyu-c-successful-pairs-of-spells-and-p:
// Time:  O(mlogm + nlogm)
// Space: O(1)

// binary search
class Solution {
public:
    vector<int> successfulPairs(vector<int>& spells, vector<int>& potions, long long success) {
        sort(begin(potions), end(potions));
        vector<int> result;
        for (const auto& s: spells) {
            result.emplace_back(size(potions) - distance(cbegin(potions), lower_bound(cbegin(potions), cend(potions), ceil_divide(success, s))));
        }
        return result;
    }

private:
    int64_t ceil_divide(int64_t a, int64_t b) {
        return (a + b - 1) / b;
    }
};

kamyu-c-sum-game-05c5flq:
// Time:  O(n)
// Space: O(1)

class Solution {
public:
    bool sumGame(string num) {
        // (1) if both halfs have '?',
        //     alice will optimally choose 9 or 0 from one half to maximize or minimize the diff of both half sums,
        //     and bob will optimally choose the same number from the other half to minimize or maximize the diff of both half sums.
        //     in the end, it turns that only one half has '?' and the diff of both half sums is still the same as original
        // (2) if smaller half has no '?', then alice wins
        // (3) if smaller half has '?'
        //     (3.1) if cnt of '?' is odd, alice can choose the last number to make the diff of both half sums != 0, then alice wins
        //     (3.2) if cnt of '?' is even
        //           (3.2.1) if larger-smaller = cnt/2 * 9, bob can always make a pair of sum 9 no matter what alice chooses, then bob wins
        //           (3.2.2) if larger-smaller > cnt/2 * 9, alice can always choose 0 no matter what bob chooses, then alice wins
        //           (3.2.3) if larger-smaller < cnt/2 * 9, alice can always choose 9 no matter what bob chooses, then alice wins
        int cnt = 0, total = 0;
        for (int i = 0; i < size(num); ++i) {
            if (num[i] == '?') {
                cnt += (i < size(num) / 2) ? -1 : 1;
            } else {
                total += (i < size(num) / 2) ? num[i] - '0' : -(num[i] - '0');
            }
        }
        return cnt % 2 ? true : total != cnt / 2 * 9;
    }
};

