                }
            }
            return result;
        };

        vector<vector<int>> adj(n);
        for (const auto& e : edges) {
            adj[e[0]].emplace_back(e[1]);
            adj[e[1]].emplace_back(e[0]);
        }
        unordered_map<int, int> cnt;
        const function<int64_t (int, int)> dfs = [&](int u, int p) {
            const auto& x = prime_factors(nums[u]);
