// Time:  O(n)
// Space: O(n)

// z-function
class Solution {
public:
    long long sumScores(string s) {
        auto z = z_function(s);
        z[0] = size(s);
        return accumulate(cbegin(z), cend(z), 0ll);
    }

private:
    // Template: https://cp-algorithms.com/string/z-function.html
    vector<int> z_function(string s) {  // Time: O(n), Space: O(n)
        vector<int> z(size(s));
        for (int i = 1, l = 0, r = 0; i < size(z); ++i) {
            if (i <= r) {
                z[i] = min (r - i + 1, z[i - l]);
            }
            while (i + z[i] < size(z) && s[z[i]] == s[i + z[i]]) {
                ++z[i];
            }
            if (i + z[i] - 1 > r) {
                l = i, r = i + z[i] - 1;
            }
        }
        return z;
    }
};

kamyu-c-sum-of-sortable-integers-0xshooo:
// Time:  O(nlog(logn))
// Space: O(n)

// prefix sum, number theory
class Solution {
public:
    int sortableIntegers(vector<int>& nums) {
        vector<int> prefix(size(nums) + 1);
        for (int i = 0; i < size(nums); ++i) {
            prefix[i + 1] = max(prefix[i], nums[i]);
        }
        vector<int> suffix(size(nums) + 1, numeric_limits<int>::max());
        for (int i = size(nums) - 1; i >= 0 ; --i) {
            suffix[i] = min(suffix[i + 1], nums[i]);
        }
        vector<int> prefix2(size(nums));
        for (int i = 0; i + 1 < size(nums); ++i) {
            prefix2[i + 1] = prefix2[i] + (nums[i] > nums[i + 1] ? 1 : 0);
        }

        const auto& check = [&](int k) {
            if (size(nums) % k) {
                return false;
            }
            for (int i = 0; i < size(nums); i += k) {
                if (!(prefix[i] <= suffix[i] && (prefix2[i + k - 1] - prefix2[i]) + (nums[i + k - 1] > nums[i] ? 1 : 0) <= 1)) {
                    return false;
                }
            }
            return true;
        };

        int result = 0;
        for (int k = 1; k <= size(nums); ++k) {
            if (check(k)) {
                result += k;
            }
        }
        return result;
    }
};

