                // assert(all(strength[j] > strength[y] for j in xrange(y+1, z+1)))
               result = add(result, mult(strength[y], sub(mult(y - x + 1, sub(prefix[z + 1], prefix[y])), mult(z - y + 1, sub(prefix[y], prefix[max(x - 1, 0)])))));
            }
            stk.emplace_back(i);
