kamyu-c-surroundedregions-1gge8qw:
// LeetCode, Surrounded Regions
// BFS method
// Complexity:
//     O(n) time, O(n) space

class Solution {
public:
    void solve(vector<vector<char>> &board) {
        if (board.empty()) return;
        const int m = board.size();
        const int n = board[0].size();

        // do BFS from up and down boundary
        for (int i = 0; i < n; i++) {
            bfs(board, 0, i);
            bfs(board, m - 1, i);
        }

        // do BFS from left and right boundary
        for (int j = 1; j < m - 1; j++) {
            bfs(board, j, 0);
            bfs(board, j, n - 1);
        }

        for (int i = 0; i < m; i++)
        	for (int j = 0; j < n; j++)
        		// mark the BFS-unvisited node with 'X'
			    if (board[i][j] == 'O')
			        board[i][j] = 'X';
			    // mark the BFS-visited node with 'O' 
			    else if (board[i][j] == '+')
			        board[i][j] = 'O';
	} 

private:
	void bfs(vector<vector<char>> &board, int i, int j) {
	    typedef pair<int, int> state_t;
	    queue<state_t> q;
	    const int m = board.size();
	    const int n = board[0].size();

	    auto is_valid = [&](const state_t &s) {
	        const int x = s.first;
	        const int y = s.second;
	        if (x < 0 || x >= m || y < 0 || y >= n || board[x][y] != 'O')
	            return false;
	        return true;
	    };

	    auto state_extend = [&](const state_t &s) {
	        vector<state_t> result;
	        const int x = s.first;
	        const int y = s.second;
	        const state_t new_states[4] = {{x-1,y}, {x+1,y},{x,y-1}, {x,y+1}};
	        for(int k=0;k<4; ++k){
	        	if (is_valid(new_states[k])) {
	        		// mark
	        		board[new_states[k].first][new_states[k].second] = '+';
	        		result.push_back(new_states[k]);
	        	} 
	        }
	        return result;
	    };

        state_t start = { i, j };
        if (is_valid(start)) {
            board[i][j] = '+';
            q.push(start);
        }

        while (!q.empty()) {
            auto cur = q.front();
            q.pop();
            auto new_states = state_extend(cur);
            for (auto s : new_states) q.push(s);
        } 
    }
};

kamyu-c-swap-adjacent-in-lr-string-1p3jc:
// Time:  O(n)
// Space: O(1)

// the following are invariant if the number of 'X' in both strings are the same
// 1. the ordering of 'L', 'R' in both strings are the same
// 2. for each position (i, j) of paired 'L' character in both strings, i >= j
// 3. for each position (i, j) of paired 'R' character in both strings, i <= j
class Solution {
public:
    bool canTransform(string start, string end) {
        int count = 0;
        for (int i = 0; i < size(start); ++i) {
            if (start[i] == 'X') {
                ++count;
            }
            if (end[i] == 'X') {
                --count;
            }
        }
        if (count) {
            return false;
        }
        for (int i = 0, j = 0; i < size(start) && j < size(end); ++i, ++j) {
            while (i < size(start) && start[i] == 'X') {
                ++i;
            }
            while (j < size(end) && end[j] == 'X') {
                ++j;
            }
            if ((i < size(start)) != (j < size(end))) {
                return false;
            }
            if (i < size(start) && j < size(end)) {
                if (start[i] != end[j] ||
                    (start[i] == 'L' && i < j) ||
                    (start[i] == 'R' && i > j)) {
                    return false;
                }
            }
        }
        return true;
    }
};

