// Time:  O(m * n)
// Space: O(k)
class Solution2 {
public:
    vector<int> kWeakestRows(vector<vector<int>>& mat, int k) {
        OrderedDict<int, bool> lookup;
        for (int j = 0; j < mat[0].size(); ++j) {
            for (int i = 0; i < mat.size(); ++i) {
                if (mat[i][j] || lookup.count(i)) {
                    continue;
                }
                lookup[i] = true;
                if (lookup.size() == k) {
