            for (const auto& [dr, dc] : DIRECTIONS) {
                const int nr = r + dr, nc = c + dc;
                if (!(0 <= nr && nr < m && 0 <= nc && nc < n && result[nr][nc] == -1)) {
                    continue;
                }
                result[nr][nc] = i;
                if (backtracking(nr, nc, i + 1)) {
                    return true;
                }
                result[nr][nc] = -1;
            }
            return false;
        };

        backtracking(r, c, 1);
        return result;
    }
