kamyu-c-the-kth-factor-of-n-0gusasu:
// Time:  O(sqrt(n))
// Space: O(1)

class Solution {
public:
    int kthFactor(int n, int k) {
        const auto& [mid, count] = kthFactor_(n);
        int total = 2 * count - (mid * mid == n);
        if (k > total) {
            return -1;
        }
        int result = kthFactor_(n, (k <= count) ? k : total - (k - 1)).first;
        return (k <= count) ? result : n / result;
    }

private:
    pair<int, int> kthFactor_(int n, int k = 0) {
        int mid = -1;
        for (int i = 1; i * i <= n; ++i) {
            if (n % i) {
                continue;
            }
            mid = i;
            if (!--k) {
                break;
            }
        }
        return {mid, -k};
    }
};

// Time:  O(sqrt(n))
// Space: O(sqrt(n))
class Solution2 {
public:
    int kthFactor(int n, int k) {
        vector<int> result;
        for (int i = 1; i * i <= n; ++i) {
            if (n % i) {
                continue;
            }
            if (i * i != n) {
                result.emplace_back(i);
            }
            if (!--k) {
                return i;
            }
        }
        return (k > result.size()) ? -1 : n / result[result.size() - k];
    }
};

kamyu-c-the-latest-time-to-catch-a-bus-1:
// Time:  O(nlogn + mlogm)
// Space: O(1)

// sort, two pointers
class Solution {
public:
    int latestTimeCatchTheBus(vector<int>& buses, vector<int>& passengers, int capacity) {
        sort(begin(buses), end(buses));
        sort(begin(passengers), end(passengers));
        int cnt = 0, j = 0;
        for (int i = 0; i < size(buses) - 1; ++i) {
            while (j < size(passengers) && passengers[j] <= buses[i]) {
                ++cnt;
                ++j;
            }
            cnt = max(cnt-capacity, 0);
        }
        j -= max(cnt - capacity, 0);
        cnt = min(cnt, capacity);
        while (j < size(passengers) && passengers[j] <= buses.back() && cnt + 1 <= capacity) {
            ++cnt;
            ++j;
        }
        if (cnt < capacity && (j - 1 < 0 || passengers[j - 1] != buses.back())) {
            return buses.back();
        }
        --j;
        for (; j; --j) {
            if (passengers[j] - 1 != passengers[j - 1]) {
                break;
            }
        }
        return passengers[j] - 1;
    }
};

