// Time:  O(n)
// Space: O(1)

class Solution {
public:
    vector<int> threeEqualParts(vector<int>& A) {
        int total = accumulate(A.cbegin(), A.cend(), 0);
        if (total % 3 != 0) {
            return {-1, -1};
        }
        if (total == 0) {
            return {0, A.size() - 1};
        }

        const auto count = total / 3;
        vector<int> nums(3);
        int c = 0;
        for (int i = 0; i < A.size(); ++i) {
            if (A[i] == 1) {
                if (c % count == 0) {
                    nums[c / count] = i;
                }
                ++c;
            } 
        }

        while (nums[2] != A.size()) {   
            if (A[nums[0]] != A[nums[1]] ||
                A[nums[0]] != A[nums[2]]) {
                return {-1, -1};
            }
            ++nums[0], ++nums[1], ++nums[2];
        }
        return {nums[0] - 1, nums[1]};
    }
};

kamyu-c-threesum2-0ype64f:
// Time Complexity: O(n^2)
// Space Complexity: O(1)

class Solution {
    public:
        vector<vector<int> > threeSum(vector<int> &num) {
            vector<vector<int> > ans;
            const int target = 0;

            sort(num.begin(), num.end());
            auto last = num.rend();
            for(auto a = num.rbegin(); a < prev(last, 2); ++a) {
                if(a > num.rbegin() && *a == *(a - 1))
                    continue;
                auto b = next(a);
                auto c = prev(last);

                while(b < c) {
                    if(b > next(a) && *b == *(b - 1)) {
                        ++b;
                    }
                    else if(c < prev(last) && *c == *(c + 1)) { 
                        --c;
                    }
                    else {
                        const int sum = *a + *b + *c;

                        if(sum < target)
                            --c;
                        else if(sum > target)
                            ++b;
                        else {
                            ans.push_back({ *c, *b, *a});
                            ++b;
                            --c;
                        }
                    }
                }
            }

            return ans;
        }
};

