// Space: O(min(m, n))

class Solution {
public:
    int maxUncrossedLines(vector<int>& A, vector<int>& B) {
        if (A.size() < B.size()) {
            return maxUncrossedLines(B, A);
        }
        vector<vector<int>> dp(2, vector<int>(B.size() + 1));
        for (int i = 0; i < A.size(); ++i) {
            for (int j = 0; j < B.size(); ++j) {
                dp[(i + 1) % 2][j + 1] = max(dp[i % 2][j] + static_cast<int>(A[i] == B[j]),
                                             max(dp[i % 2][j + 1], dp[(i + 1) % 2][j]));
            }
        }
        return dp[(A.size()) % 2][B.size()];
    }
};

kamyu-c-unique-3-digit-even-numbers-0042:
// Time:  O(n)
// Space: O(1)

// freq table, combinatorics
class Solution {
public:
    int totalNumbers(vector<int>& digits) {
        vector<int> cnt(10);
        for (const auto& x : digits) {
            ++cnt[x];
        }
        int odd = 0, even = 0;
        for (int i = 0; i < size(cnt); ++i) {
            if (cnt[i] == 0) {
                continue;
            }
            if (i % 2) {
                ++odd;
            } else {
                ++even;
            }
        }

        int result = 0;
        // 3 same digits
        for (int i = 2; i < size(cnt); i += 2) {
            if (cnt[i] >= 3) {
                ++result;  // eee
            }
        }
        // 3 distinct digits
        result += even * (odd + even - 1) * (odd + even - 2);  // xye
        if (cnt[0]) {
            result -= 1 * (even - 1) * (odd + even - 2);  // 0xe
        }
        // 2 same digits, 1 different digit
        for (int i = 0; i < size(cnt); ++i) {
            if (cnt[i] < 2) {
                continue;
            }
            if (i == 0) {
                result += (odd + even) - 1;  // x00
            } else if (i % 2) {
                result += even;  // ooe
            } else {
                result += 3 * (even - 1) - (cnt[0] != 0 ? 1 : 0);  // eeE, eEe, Eee excluding 0ee
                result += 2 * odd;  // eoe, oee
            }
        }
        return result;
    }
};

kamyu-c-unique-binary-search-trees-ii-1y:
// Time:  O(n * 4^n / n^(3/2)) ~= Catalan numbers
// Space: O(n)

/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode(int x) : val(x), left(NULL), right(NULL) {}
 * };
 */
class Solution {
public:
    vector<TreeNode*> generateTrees(int n) {
        if (n == 0) {
            return {};
        }
        return generateTreesHelper(1, n);
    }

private:
    vector<TreeNode *> generateTreesHelper(int start, int end) {
        vector<TreeNode *> result;
        if (start > end) {
            result.emplace_back(nullptr);
            return result;
        }

        for (int i = start; i <= end; ++i) {
            vector<TreeNode *> leftSubTrees = generateTreesHelper(start, i - 1);
            vector<TreeNode *> rightSubTrees = generateTreesHelper(i + 1, end);
            for (const auto& left : leftSubTrees) {
                for (const auto& right : rightSubTrees) {
                    TreeNode *root = new TreeNode(i);
                    root->left = clone(left);
                    root->right = clone(right);
                    result.emplace_back(root);
                }
            }

        }
        return result;
    }

    TreeNode *clone(TreeNode *root) {
        TreeNode *newRoot = nullptr;

        if (root) {
            newRoot = new TreeNode(root->val);
            newRoot->left = clone(root->left);
            newRoot->right = clone(root->right);
        }

        return newRoot;
    }
};

