class Solution {
public:
    int uniqueEmailGroups(vector<string>& emails) {
        const auto& lower = [](const auto& s) {
            string result(s);
            for (auto& x : result) {
                x = tolower(x);
            }
            return result;
        };

        unordered_set<string> result;
        for (auto& email : emails) {
            email = lower(email);
            auto local = email.substr(0, email.find_first_of("+@"));
