// Space: O(9)

// Better performance solution.
class Solution {
public:
    bool isValidSudoku(const vector<vector<char>>& board) {
        // Check row constraints.
        for (int i = 0; i < 9; ++i) {
            if (anyDuplicate(board, i, i + 1, 0, 9)) {
                return false;
            }
        }

        // Check column constraints.
        for (int j = 0; j < board.size(); ++j) {
            if (anyDuplicate(board, 0, 9, j, j + 1)) {
                return false;
            }
        }

        // Check region constraints.
        for (int i = 0; i < 9; i += 3) {
            for (int j = 0; j < 9; j += 3) {
                if (anyDuplicate(board, i, i + 3, j, j + 3)) {
                    return false;
                }
            }
        }
        return true;
    }

private:
    // Return true if subarray board[start_row : end_row - 1][start_col : end_col - 1]
    // contains any duplicates in [1 : num_elements]; otherwise return false.
    bool anyDuplicate(const vector<vector<char>>& board, int start_row, int end_row,
                      int start_col, int end_col) {
        bitset<9> is_present;
        for (int i = start_row; i < end_row; ++i) {
            for (int j = start_col; j < end_col; ++j) {
                if (board[i][j] != '.') {
                    if (is_present[board[i][j] - '1']) {
                        return true;
                    }
                    is_present.flip(board[i][j] - '1');
                }
            }
        }
        return false;
    }
};


// Time:  O(9^2)
// Space: O(9)
// More generic solution.
class Solution2 {
public:
    bool isValidSudoku(const vector<vector<char>>& board) {
        // Check row constraints.
        for (int i = 0; i < board.size(); ++i) {
            if (anyDuplicate(board, i, i + 1, 0, board.size(), board.size())) {
                return false;
            }
        }

        // Check column constraints.
        for (int j = 0; j < board.size(); ++j) {
            if (anyDuplicate(board, 0, board.size(), j, j + 1, board.size())) {
                return false;
            }
        }

        // Check region constraints.
        int region_size = sqrt(board.size());
        for (int i = 0; i < board.size(); i += region_size) {
            for (int j = 0; j < board.size(); j += region_size) {
                if (anyDuplicate(board,
                                 i, i + region_size,
                                 j, j + region_size,
                                 board.size())) {
                    return false;
                }
            }
        }
        return true;
    }

private:
    // Return true if subarray board[start_row : end_row - 1][start_col : end_col - 1]
    // contains any duplicates in [1 : num_elements]; otherwise return false.
    bool anyDuplicate(const vector<vector<char>>& board, int start_row, int end_row,
                      int start_col, int end_col, int num_elements) {
        vector<bool> is_present(num_elements + 1, false);
        for (int i = start_row; i < end_row; ++i) {
            for (int j = start_col; j < end_col; ++j) {
                if (board[i][j] != '.') {
                    if (is_present[board[i][j] - '0']) {
                        return true;
                    }
                    is_present[board[i][j] - '0'] = true;
                }
            }
        }
        return false;
    }
};

kamyu-c-valid-tic-tac-toe-state-0az6vqb:
// Time:  O(1)
// Space: O(1)

class Solution {
public:
    bool validTicTacToe(vector<string>& board) {
        const auto FIRST = 'X', SECOND = 'O';
        const auto x_count =
            accumulate(board.cbegin(), board.cend(), 0,
                       [&FIRST](int accu, const string& s) {
                           return accu + count(s.cbegin(), s.cend(), FIRST);
                       });
        const auto o_count =
            accumulate(board.cbegin(), board.cend(), 0,
                       [&SECOND](int accu, const string& s) {
                           return accu + count(s.cbegin(), s.cend(), SECOND);
                       });
        if (o_count != x_count - 1 && o_count != x_count) {
            return false;
        }
        if (isWin(board, FIRST) && o_count != x_count - 1) {
            return false;
        }
        if (isWin(board, SECOND) && o_count != x_count) {
            return false;
        }
        return true;
    }

private:
    bool isWin(const vector<string>& board, char player) {
        for (int i = 0; i < board.size(); ++i) {
            if (all_of(board[i].cbegin(), board[i].cend(),
                       [&player](const char& c) {
                           return c == player;
                       })) {
                return true;
            }
            if (all_of(board.cbegin(), board.cend(),
                       [&i, &player](const string& row) {
                           return row[i] == player;
                       })) {
                return true;
            }
        }

        return (player == board[1][1] &&
                board[1][1] == board[0][0] &&
                board[0][0] == board[2][2]) ||
               (player == board[1][1] &&
                board[1][1] == board[0][2] &&
                board[0][2] == board[2][0]);
    }
};

