            visited[i][j] = true;  // set value
            bool ret = dfs(board, word, index + 1,  i + 1, j, visited) 
                || dfs(board, word, index + 1,  i, j + 1, visited) 
                || dfs(board, word, index + 1,  i - 1, j, visited) 
                || dfs(board, word, index + 1,  i, j - 1, visited);
            visited[i][j] = false; // recover value

            return ret;
        }
};

